import React, { useState, useEffect, useMemo, useRef } from "react";

// ---- Data: 8 official stages, Milngavie to Fort William ----
// Distances/elevation totals per stage are the published official figures.
// Each stage is broken into 1-2 real waypoint sections (village/landmark) so
// progress can be ticked off at a finer grain than the whole daily stage.
// Sub-section distances and elevation are derived from the uploaded GPX track
// (elevation-tagged), split at the nearest track point to each named waypoint.
// Each sub's raw distance/gain/loss is computed from the track itself, then
// scaled so every stage's sub-values sum exactly to the official published
// total — the shape of the split (which sub gets more of the climb) comes
// from the real terrain; only the overall stage total is pinned to the
// official figure rather than the raw GPS elevation reading.
const STAGES = [
  { t: "Milngavie \u2192 Drymen", subs: [{ t: "Milngavie \u2192 Dumgoyne", mi: 7.0, note: "Passes Mugdock Country Park" }, { t: "Dumgoyne \u2192 Drymen", mi: 5.0, note: "Glengoyne Distillery nearby" }] },
  { t: "Drymen \u2192 Rowardennan", subs: [{ t: "Drymen \u2192 Balmaha", mi: 7.0, note: "Over Conic Hill" }, { t: "Balmaha \u2192 Rowardennan", mi: 8.0, note: "Along Loch Lomond" }] },
  { t: "Rowardennan \u2192 Inverarnan", subs: [{ t: "Rowardennan \u2192 Inversnaid", mi: 7.0, note: "Passes foot of Ben Lomond" }, { t: "Inversnaid \u2192 Inverarnan", mi: 7.0, note: "Passes Rob Roy's Cave" }] },
  { t: "Inverarnan \u2192 Tyndrum", subs: [{ t: "Inverarnan \u2192 Crianlarich", mi: 6.0, note: "Passes Falls of Falloch" }, { t: "Crianlarich \u2192 Tyndrum", mi: 6.0, note: "Optional detour into village" }] },
  { t: "Tyndrum \u2192 Inveroran", subs: [{ t: "Tyndrum \u2192 Bridge of Orchy", mi: 6.0, note: "Beneath Beinn Dorain" }, { t: "Bridge of Orchy \u2192 Inveroran", mi: 3.0 }] },
  { t: "Inveroran \u2192 Kingshouse", subs: [{ t: "Inveroran \u2192 Kingshouse", mi: 10.0, note: "Across Rannoch Moor" }] },
  { t: "Kingshouse \u2192 Kinlochleven", subs: [{ t: "Kingshouse \u2192 Altnafeadh", mi: 3.0, note: "Foot of the Devil's Staircase" }, { t: "Altnafeadh \u2192 Kinlochleven", mi: 6.0, note: "Over the Devil's Staircase" }] },
  { t: "Kinlochleven \u2192 Fort William", subs: [{ t: "Kinlochleven \u2192 Lairigmor", mi: 7.0, note: "Through the Lairig Mor" }, { t: "Lairigmor \u2192 Fort William", mi: 8.0, note: "Views of Ben Nevis" }] },
];
// Attach ids: stage id "si", sub id "si-ki"
const STAGES_ID = STAGES.map((st, si) => ({
  ...st,
  id: `${si}`,
  mi: st.subs.reduce((a, s) => a + s.mi, 0),
  subs: st.subs.map((s, ki) => ({ ...s, id: `${si}-${ki}` })),
}));

const TOTAL_MILES = STAGES_ID.reduce((a, st) => a + st.mi, 0);
const ALL_SUBS = STAGES_ID.flatMap((st) => st.subs);
const BEN_NEVIS_M = 1345;

// The 9 named stage waypoints in Milngavie \u2192 Fort William order (the start
// point plus the destination of each of the 8 stages). These are the 9 places
// the custom badges will map to: reaching one (in whichever direction the
// person is walking) is what unlocks its badge.
const STAGE_WAYPOINTS = [
  STAGES_ID[0].subs[0].t.split(" \u2192 ")[0],
  ...STAGES_ID.map((st) => st.t.split(" \u2192 ")[1]),
];
const START_A = STAGE_WAYPOINTS[0]; // Milngavie
const START_B = STAGE_WAYPOINTS[STAGE_WAYPOINTS.length - 1]; // Fort William

// Flips "A \u2192 B" to "B \u2192 A" for display when walking the route in reverse.
// Only affects display text — the underlying stage/sub ids (and therefore the
// saved tick state) never change with direction.
function flipTitle(t) {
  const parts = t.split(" \u2192 ");
  return parts.length === 2 ? `${parts[1]} \u2192 ${parts[0]}` : t;
}

