const ELEVATION = {"0-0": {"gain": 141, "loss": 171}, "0-1": {"gain": 101, "loss": 62}, "1-0": {"gain": 347, "loss": 391}, "1-1": {"gain": 257, "loss": 250}, "2-0": {"gain": 259, "loss": 265}, "2-1": {"gain": 198, "loss": 198}, "3-0": {"gain": 358, "loss": 137}, "3-1": {"gain": 188, "loss": 211}, "4-0": {"gain": 103, "loss": 205}, "4-1": {"gain": 184, "loss": 141}, "5-0": {"gain": 362, "loss": 264}, "6-0": {"gain": 184, "loss": 89}, "6-1": {"gain": 195, "loss": 525}, "7-0": {"gain": 340, "loss": 225}, "7-1": {"gain": 308, "loss": 423}};
